    private static final String[] TABS={"Объект","Связи","Телепорты","События","Диагностика","Управление"};
    private JsonObject view;private int tab,page,rowsPerPage,left,central,right,columnWidth,bodyTop=80,bodyBottom;private boolean details,confirm;
    private final List<Row> rows=new ArrayList<>();private final List<String> rightLines=new ArrayList<>();
    private String draftName="",draftCondition="ANY",draftEffect="TOGGLE",draftLine="",draftLampName="",draftNewLineName="",draftCommand="",draftOffset="0",draftNote="",draftMount="VERTICAL";
    private boolean draftBoth=true,draftManual,commandOpen=true,draftDogs;private int commandIndex=-1;private List<String> commandDraft=new ArrayList<>();
    private final boolean[] dirty=new boolean[6];private final Map<Boolean,List<String>> commandBuffers=new HashMap<>();
    private boolean exitPrompt,saving,serverChanged,confirmConflicts;private String draftTarget="",draftVersion="",draftLampVersion="",pendingId="",pendingOp="";private int savingTab=-1;private JsonObject conflictingView;
    private final Set<Integer> savingTabs=new HashSet<>();
