    public BuilderScreen(JsonObject view){super(Text.literal("Строительный инструмент"));this.view=view;resetDraft();}
    public void accept(JsonObject next){
        JsonObject previousTarget=target().deepCopy(),previousRule=rule().deepCopy();boolean same=string(previousTarget,"instance","").equals(string(object(next,"target"),"instance",""));String previousVersion=draftVersion;view=next;
        boolean acknowledgement=pendingId.equals(string(next,"requestId",""))&&!pendingId.isBlank();
        if(acknowledgement){String message=string(next,"message","");boolean success=bool(next,"accepted");if(success&&pendingOp.equals("lamp")){draftLampVersion=string(view,"lampVersion","");draftLine=string(view,"lampLine",draftLine);}pendingId="";pendingOp="";
            if(saving&&success){draftVersion=string(target(),"version","");draftLampVersion=string(view,"lampVersion","");if(!saveQueue.isEmpty()){sendNextSave();return;}for(int saved:savingTabs)dirty[saved]=false;savingTabs.clear();saving=false;resetCleanDrafts();if(afterSave!=null){Runnable done=afterSave;afterSave=null;done.run();return;}}
            else if(saving){saveQueue.clear();saving=false;afterSave=null;serverChanged=message.startsWith("Данные изменились");}
        }
        if(!same){if(hasDirty()){conflictingView=next.deepCopy();view.add("target",previousTarget);view.add("rule",previousRule);serverChanged=true;return;}resetDraft();}
        else if(hasDirty()){if(!previousVersion.isBlank()&&!previousVersion.equals(string(target(),"version",previousVersion))&&!acknowledgement)serverChanged=true;}
        else resetDraft();
        // A periodic server refresh must not destroy a focused editor between
        // the focus click and the first character (diagnostic notes are not drafts).
        // Explicit acknowledgements/context changes still rebuild the form.
        if((!hasDirty()&&!textFieldFocused())||acknowledgement||!same)clearAndInit();
    }
    private boolean textFieldFocused(){return children().stream().anyMatch(element->element instanceof TextFieldWidget field&&field.isFocused());}
    public JsonObject currentView(){return view.deepCopy();}
    @Override public boolean shouldPause(){return false;}
    private JsonObject target(){return object(view,"target");}
    private JsonObject rule(){return object(view,"rule");}
    private void resetDraft(){Arrays.fill(dirty,false);serverChanged=false;draftTarget=string(target(),"instance","");draftVersion=string(target(),"version","");draftLampVersion=string(view,"lampVersion","");commandBuffers.clear();resetCleanDrafts();}
    private void resetCleanDrafts(){JsonObject t=target(),r=rule();if(!dirty[0]){draftOffset=string(t,"offset","0");draftManual=bool(t,"leversOnly");draftDogs=bool(t,"dogsVisible");draftMount=string(t,"mountValue","VERTICAL");}if(!dirty[1]){draftName=string(r,"name","");draftCondition=string(r,"condition","ANY");draftEffect=string(r,"effect","TOGGLE");}if(!dirty[2]){draftLine=string(view,"lampLine","");if(draftLine.isBlank())draftLine="Охотничья линия";draftBoth=!view.has("lampBoth")||bool(view,"lampBoth");draftLampName=string(object(object(view,"currentLamp"),"node"),"name","");}if(!dirty[3]){commandBuffers.clear();loadCommands();}}
